sys.path.insert(0, str(root / 'Ivan/hw3'))
import run

archive = run.OUTPUTS / 'full500'
output = run.OUTPUTS / 'manual_check'
evaluation = archive / 'evaluation'
manifest = json.loads((evaluation / 'run_manifest.json').read_text(encoding='utf-8'))
protocol = json.loads((archive / 'protocol.json').read_text(encoding='utf-8'))
users = manifest['users']
if len(users) != 500 or len(set(users)) != 500 or run.digest(users) != protocol['cohort_sha256']:
    raise ValueError('Unexpected archived cohort or order')
if manifest['runtime']['protocol_sha256'] != protocol['protocol_sha256']:
    raise ValueError('Archived protocol mismatch')

methods = ('cbf', 'MaxSim', 'MeanSim')
names = {'cbf': 'CBF', 'MaxSim': 'MaxSim', 'MeanSim': 'MeanSim'}
rows = json.loads((evaluation / 'per_user.json').read_text(encoding='utf-8'), parse_float=str)
grades = {(row['user_id'], row['method']): row for row in rows if row['method'] in methods}
if len(grades) != 500 * len(methods):
    raise ValueError('Incomplete archived scores')
chosen = next(
    (uid for uid in users[100:]
     if Decimal(grades[uid, 'MeanSim']['ndcg_at_10']) > Decimal(grades[uid, 'MaxSim']['ndcg_at_10'])),
    None,
)
if chosen is None:
    print('NO_MATCH')
    raise SystemExit(0)

starter, _, _, truth, contexts, baselines, _, _, reconstructed = run.load_bundle(root / 'data')
if any(manifest[key] != value for key, value in reconstructed.items()):
    raise ValueError('Local inputs do not match the archived evaluation')
context = contexts[chosen]
targets = sorted(truth.get(chosen, set()) & set(context['eligible_asset_ids']))
if not targets or any(len(targets) != grades[chosen, method]['relevant_count'] for method in methods):
    raise ValueError('Complete target set does not match the archive')

rankings = {method: [] for method in methods}
with (evaluation / 'predictions.csv').open(encoding='utf-8', newline='') as stream:
    for row in csv.DictReader(stream):
        if row['user_id'] == chosen and row['method'] in rankings:
            rankings[row['method']].append((int(row['rank']), row['ISIN']))
for method, ranked in rankings.items():
    ranked.sort()
    if [rank for rank, _ in ranked] != list(range(1, 11)):
        raise ValueError('Unexpected archived rank sequence')
    starter.validate_ranking([isin for _, isin in ranked], context['eligible_asset_ids'])
if [isin for _, isin in rankings['cbf']] != baselines[chosen]['cbf']:
    raise ValueError('Archived CBF order does not match the starter')

case = ['Пользователь U01', '', 'Все релевантные активы (ISIN)']
case.extend(targets)
for method in methods:
    case.extend(('', f'Top-10 {names[method]}'))
    case.extend(f'{rank:2d}. {isin}' for rank, isin in rankings[method])
case_text = '\n'.join(case) + '\n'
answer_text = 'Пользователь U01. Сохранённые значения nDCG@10.\n\n' + ''.join(
    f"{names[method]}\t{grades[chosen, method]['ndcg_at_10']}\n" for method in methods
)
output.mkdir(exist_ok=True)
for name, body in (('case.txt', case_text), ('answer.txt', answer_text)):
    path = output / name
    if path.exists() and path.read_text(encoding='utf-8') != body:
        raise ValueError('A different manual-check file already exists')
for name, body in (('case.txt', case_text), ('answer.txt', answer_text)):
    path = output / name
    if not path.exists():
        with path.open('x', encoding='utf-8') as stream:
            stream.write(body)
    if path.read_text(encoding='utf-8') != body:
        raise ValueError('Manual-check file verification failed')
print('CREATED_AND_VERIFIED')
