from hashlib import sha256
from pathlib import Path
import shutil
from tempfile import TemporaryDirectory

root = Path('Ivan/hw3')
results = root / 'results'
results.mkdir(exist_ok=True)
for source, target in (
    (root / 'test_run.py', root / 'tests/test_run.py'),
    (root / 'failure_analysis.json', results / 'failure_analysis.json'),
):
    if target.exists():
        raise FileExistsError(target)
    source.rename(target)

def inventory(directory):
    return {
        str(path.relative_to(directory)): (
            ('symlink', str(path.readlink())) if path.is_symlink()
            else ('directory',) if path.is_dir()
            else ('file', sha256(path.read_bytes()).hexdigest())
        )
        for path in directory.rglob('*')
    }

source = root / 'outputs/full500'
archive = results / 'final_results'
if archive.exists():
    raise FileExistsError(archive)
expected = inventory(source)
with TemporaryDirectory(prefix='.archive-', dir=results) as folder:
    staged = Path(folder) / 'full500'
    shutil.copytree(source, staged, symlinks=True)
    if inventory(staged) != expected or inventory(source) != expected:
        raise ValueError('Archive inventory mismatch')
    staged.rename(archive)
if inventory(archive) != expected:
    raise ValueError('Published archive differs from the completed run')
print(f"Verified archive files: {sum(value[0] == 'file' for value in expected.values())}")
PY`;
